 WHERE slug = 'aider' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "What is Aider?", "a": "Aider is an open-source AI coding assistant that runs in the terminal. It connects to AI models (Claude, GPT, Gemini) and can edit multiple files simultaneously, automatically committing changes to git after each step."}, {"q": "Is Aider better than GitHub Copilot?", "a": "They serve different workflows. Aider is better for autonomous multi-file refactoring from the command line. Copilot is better for real-time inline suggestions inside an IDE. Many developers use both."}, {"q": "Is Aider free?", "a": "Aider itself is free and open-source. You pay for the AI model API you connect it to — Claude or GPT API costs apply per token used."}]$x$::jsonb
 WHERE slug = 'aider' AND lang = 'en';

