UPDATE tools SET faq = $x$[{"a": "Aider es un asistente de codificación de IA open-source que funciona en la terminal. Se conecta a modelos de IA (Claude, GPT, Gemini) y puede editar múltiples archivos simultáneamente, haciendo un commit automático de los cambios en git después de cada paso.", "q": "¿Qué es Aider?"}, {"a": "Son para casos de uso diferentes. Aider es mejor para refactorización autónoma de múltiples archivos desde la línea de comandos. Copilot es mejor para sugerencias en línea en tiempo real dentro del IDE. Muchos desarrolladores usan ambas.", "q": "¿Aider es mejor que GitHub Copilot?"}, {"a": "Aider como herramienta es gratuito y open-source. Pagas por la API del modelo — los costos de Claude o GPT API se calculan por tokens usados.", "q": "¿Aider es gratuito?"}]$x$::jsonb
 WHERE slug = 'aider' AND lang = 'es';

UPDATE tools SET pros = ARRAY[$x$Jede KI-Änderung wird automatisch zu Git committed — vollständig nachvollziehbar und rückgängig machbar$x$, $x$Repo-Map ermöglicht präzise Multi-File-Edits in großen Codebases$x$, $x$Verbindung zu jedem LLM: Claude, GPT, Gemini, DeepSeek, lokale Ollama$x$, $x$Kein IDE-Plugin erforderlich — funktioniert in jedem Verzeichnis vom Terminal$x$, $x$Spracheingabemodus und Bildunterstützung für visuelles Debugging$x$]::text[]
