UPDATE tools SET choose_if = $x$["✅ Sie bevorzugen Terminal-basierte Workflows und möchten KI-Coding direkt in der Befehlszeile", "✅ Sie möchten KI-Coding, das nahtlos mit Git integriert ist: automatische Commits nach jeder Änderung", "✅ Sie möchten mehrere Dateien gleichzeitig mit einer einzigen Anweisung bearbeiten", "✅ Sie möchten ein Open-Source-Tool das mit Claude, GPT oder lokalen Modellen funktioniert"]$x$::jsonb
 WHERE slug = 'aider' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Was ist Aider?", "a": "Aider ist ein Open-Source KI-Coding-Assistent für das Terminal. Sie starten Aider in Ihrem Projekt-Verzeichnis, wählen das Modell (Claude, GPT, Gemini etc.) und können dann in natürlicher Sprache Änderungen anfordern. Aider ändert die Dateien und erstellt automatisch Git-Commits."}, {"q": "Ist Aider kostenlos?", "a": "Aider selbst ist kostenlos und Open-Source. Die Kosten entstehen durch das verwendete Modell — die API-Nutzung bei Anbietern wie Claude, GPT oder anderen. Mit Ollama und lokalen Modellen kann Aider vollständig kostenlos genutzt werden."}, {"q": "Aider vs Claude Code: Was ist besser?", "a": "Beide sind Terminal-basierte KI-Coding-Agenten. Claude Code ist tiefer in Anthropics Claude-Ökosystem integriert und generell leistungsfähiger für komplexe Aufgaben. Aider ist Open-Source, modellflexibel und hat eine aktive Community. Claude Code für maximale Qualität; Aider für Open-Source-Flexibilität."}, {"q": "Welche Programmiersprachen unterstützt Aider?", "a": "Aider versteht praktisch alle Programmiersprachen da es auf LLMs basiert. Es hat spezifische Unterstützung für das Repository-Mapping bei Python, JavaScript, TypeScript, Go, Java, C++, Ruby und weiteren gängigen Sprachen, was Aider hilft, den Code-Kontext besser zu verstehen."}]$x$::jsonb
 WHERE slug = 'aider' AND lang = 'de';

