 WHERE slug = 'aider' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Aider — это open-source ИИ-ассистент для написания кода, работающий в терминале. Он подключается к ИИ-моделям (Claude, GPT, Gemini) и может редактировать несколько файлов одновременно, автоматически фиксируя изменения в git после каждого шага.", "q": "Что такое Aider?"}, {"a": "Они подходят для разных задач. Aider лучше для автономного рефакторинга нескольких файлов из командной строки. Copilot лучше для встроенных подсказок в реальном времени внутри IDE. Многие разработчики используют оба инструмента.", "q": "Aider лучше GitHub Copilot?"}]$x$::jsonb
 WHERE slug = 'aider' AND lang = 'ru';

