UPDATE tools SET choose_if = $x$["✅ Vous avez besoin d'un agent IA open-source gratuit dans VS Code avec un contrôle maximal", "✅ Cline (anciennement Claude Dev) effectue des tâches autonomes : lit des fichiers, écrit du code, exécute des commandes", "✅ Supporte n'importe quel modèle : Claude, GPT, Gemini, modèles locaux — vous choisissez", "✅ Cline est open-source et gratuit — vous ne payez que pour l'API du modèle que vous choisissez"]$x$::jsonb
