UPDATE tools SET faq = $x$[{"a": "Cline est gratuit et open-source avec plus de flexibilité de modèles et de capacités agentiques. Copilot est plus pratique et plus mature. Pour la flexibilité open-source, Cline ; pour un assistant quotidien stable, Copilot.", "q": "Cline vs GitHub Copilot — lequel est le meilleur ?"}, {"a": "L'extension Cline est gratuite. Vous payez pour l'API du modèle : API Claude, API OpenAI ou localement via Ollama gratuitement. GitHub Copilot — à partir de 10 $/mois.", "q": "Cline est-il gratuit ?"}, {"a": "Cline (anciennement Claude Dev) est un agent IA open-source pour VS Code. Il peut lire et écrire des fichiers de manière autonome, exécuter des commandes terminal et apporter des modifications à la base de code. Supporte Claude, GPT, Gemini et d'autres modèles via votre propre clé API.", "q": "Qu'est-ce que Cline ?"}, {"a": "Cline est une extension VS Code ; vous restez dans VS Code. Cursor est un éditeur séparé. Cline est moins cher ; Cursor a une intégration agentique plus profonde. Pour rester dans VS Code, Cline ; pour un éditeur IA complet, Cursor.", "q": "Cline vs Cursor — lequel choisir ?"}]$x$::jsonb
 WHERE slug = 'cline' AND lang = 'fr';

