 WHERE slug = 'cline' AND lang = 'pt';

UPDATE tools SET choose_if = $x$["✅ Você precisa de um agente de IA open-source gratuito no VS Code com controle máximo", "✅ Cline (anteriormente Claude Dev) realiza tarefas autônomas: lê arquivos, escreve código, executa comandos", "✅ Suporta qualquer modelo: Claude, GPT, Gemini, locais — você escolhe", "✅ Cline é open-source e gratuito — você paga apenas pela API do modelo que escolher"]$x$::jsonb
 WHERE slug = 'cline' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "Cline vs GitHub Copilot — qual é o melhor?", "a": "Cline é gratuito e open-source com mais flexibilidade de modelos e capacidades agênticas. Copilot é mais conveniente e maduro. Para flexibilidade open-source, Cline; para um assistente diário estável, Copilot."}, {"q": "Cline é gratuito?", "a": "A extensão Cline é gratuita. Você paga pela API do modelo: API Claude, API OpenAI ou localmente via Ollama gratuitamente. GitHub Copilot — a partir de $10/mês."}, {"q": "O que é Cline?", "a": "Cline (anteriormente Claude Dev) é um agente de IA open-source para VS Code. Ele pode ler e escrever arquivos autonomamente, executar comandos de terminal e fazer alterações na base de código. Suporta Claude, GPT, Gemini e outros modelos via sua própria chave de API."}, {"q": "Cline vs Cursor — qual escolher?", "a": "Cline é uma extensão do VS Code; você permanece no VS Code. Cursor é um editor separado. Cline é mais barato; Cursor tem integração agêntica mais profunda. Para ficar no VS Code, Cline; para um editor de IA completo, Cursor."}]$x$::jsonb
 WHERE slug = 'cline' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "What is Consensus AI?", "a": "Consensus is an AI-powered academic research engine that searches a corpus cited at over 220 million peer-reviewed papers. It extracts key findings, can show consensus-meter style agreement across studies, and provides cited answers — with modes for general research, deep multi-step search, and medical questions."}, {"q": "Is Consensus free?", "a": "Consensus has a free plan with basic Quick Search, abstract summaries, limited Pro messages, and about 3 Deep Searches a month. The Pro plan is $10/month and unlocks unlimited Pro search, a larger Deep Search allotment, Study Snapshots, and full export. There's also a Student plan at $9/month with .edu/.ac verification, and a higher Deep tier reported at $45/user/month with around 200 Deep Searches a month and unlimited snapshots."}, {"q": "What is the difference between Consensus and Google Scholar?", "a": "Google Scholar is a search index — it finds papers but you have to read them yourself. Consensus uses AI to extract key findings from papers and synthesize them into direct answers, with a consensus-meter feature showing how much agreement exists across studies. Consensus saves significant reading time."}]$x$::jsonb
 WHERE slug = 'consensus' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "What is Continue.dev?", "a": "Continue.dev was an open-source AI coding assistant that worked as an IDE extension for VS Code and JetBrains, letting you connect to any LLM - OpenAI, Anthropic, local models via Ollama, or others - for AI code suggestions and chat without being locked into a single provider. As of v2.0.0 (its final release, around June 2026), the standalone product has been discontinued after Cursor (Anysphere) acqui-hired the Continue team. The extensions remain free under Apache 2.0 but are no longer maintained."}, {"q": "Is Continue.dev free?", "a": "Yes, the open-source IDE extensions and CLI remain free under Apache 2.0. Your only real cost was ever the API tokens for whatever model provider you connected, or $0 if you run local models. The former paid Continue Hub plans are no longer purchasable, and recurring billing has been disabled for existing subscribers."}, {"q": "Can Continue.dev use local models?", "a": "Yes. Connecting to local models via Ollama for private, offline coding assistance with no API costs was one of Continue.dev's key features, and nothing has been removed from the released builds. However, since the project is now unmaintained and the repository is read-only, there will be no further updates, bug fixes, or vendor support going forward."}, {"q": "Is Continue.dev better than Cursor?", "a": "This comparison is largely moot now: Cursor (Anysphere) acqui-hired the Continue.dev team around mid-June 2026, and Continue is effectively end-of-life as a standalone product, with its final release already out and the repository switched to read-only. Continue.dev's extensions remain free and usable for those who want a self-managed, model-agnostic setup, but anyone wanting an actively supported, forward-looking tool should look at Cursor or another maintained alternative."}]$x$::jsonb
 WHERE slug = 'continue-dev' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "Was ist Continue.dev?", "a": "Continue.dev war ein Open-Source KI-Coding-Assistent für VS Code, JetBrains und die Kommandozeile, bei dem man das Modell selbst wählen konnte — von OpenAI, Anthropic, lokalen Ollama-Modellen oder anderen Anbietern. Seit Mitte 2026 ist das Produkt als eigenständiges Tool eingestellt: Das Team wurde von Cursor (Anysphere) übernommen, die Erweiterungen bleiben unter Apache 2.0 kostenlos nutzbar, werden aber nicht mehr weiterentwickelt."}, {"q": "Ist Continue.dev wirklich kostenlos?", "a": "Ja, die IDE-Erweiterungen und die CLI sind Open-Source unter Apache 2.0 und bleiben kostenlos. Man zahlt höchstens für die API-Tokens des gewählten Modells, oder gar nichts bei lokalen Modellen über Ollama. Die früheren kostenpflichtigen Continue-Hub-Pläne (Solo, Teams, Enterprise) sind seit der Einstellung des Produkts nicht mehr buchbar, laufende Abos werden nicht weiter abgerechnet. Zu beachten: Das Projekt wird nicht mehr gepflegt, Sicherheits- und Kompatibilitätsprobleme werden künftig nicht mehr behoben."}, {"q": "Continue.dev mit lokalen Modellen: Wie gut ist das?", "a": "Continue.dev erlaubte den Einsatz lokaler Modelle über Ollama für Code-Vervollständigung, Chat und codebasierte Bearbeitungen, ohne an einen Anbieter gebunden zu sein. Wer Datenschutz und Kosteneinsparung priorisiert, findet hier weiterhin eine funktionierende Lösung. Da das Projekt aber seit Mitte 2026 nicht mehr weiterentwickelt wird und das GitHub-Repository nur noch lesbar ist, sollte man mit langfristiger Unterstützung nicht mehr rechnen."}, {"q": "GitHub Copilot vs Continue.dev: Wer gewinnt?", "a": "Copilot ist ein aktiv weiterentwickeltes, kommerzielles Produkt mit kontinuierlichem Support. Continue.dev war flexibler, kostenlos und modell-agnostisch, ist aber seit der Übernahme durch Cursor (Anysphere) im Jahr 2026 als eigenständiges Tool eingestellt und wird nicht mehr gepflegt. Für aktive Weiterentwicklung und Support ist Copilot oder ein anderes gepflegtes Tool wie Cursor die sicherere Wahl; wer ein archiviertes, kostenloses Open-Source-Tool selbst verwalten möchte, kann weiterhin auf Continue.dev zurückgreifen."}]$x$::jsonb
 WHERE slug = 'continue-dev' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Что такое Continue.dev?", "a": "Continue.dev — open-source плагин для VS Code и JetBrains, добавляющий ИИ-функции: автодополнение, чат и редактирование. Уникальная особенность — поддержка любой модели: Claude, GPT, Gemini или локальные через Ollama."}, {"q": "Continue.dev так же хорош, как Copilot?", "a": "С сильными моделями (Claude, GPT) — качество сравнимо. Copilot более отполирован и прост в использовании. Continue.dev выигрывает в гибкости и стоимости при использовании локальных моделей."}]$x$::jsonb
 WHERE slug = 'continue-dev' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Continue.dev ?", "a": "Continue.dev est un assistant de codage IA open-source pour VS Code, JetBrains et en CLI, qui se connecte à n'importe quel LLM (OpenAI, Anthropic, modèles locaux via Ollama, ou d'autres fournisseurs). Depuis que l'équipe a été rachetée par Cursor (Anysphere) et que la version finale v2.0.0 est sortie, le produit n'est plus développé activement, mais les extensions restent gratuites sous licence Apache 2.0."}, {"q": "Continue.dev est-il vraiment gratuit ?", "a": "Continue.dev reste gratuit et open-source sous licence Apache 2.0. Vous ne payez que pour les tokens d'API du fournisseur de modèle choisi (OpenAI, Anthropic, etc.), ou rien du tout si vous utilisez des modèles locaux comme Ollama. Les anciens forfaits payants du Continue Hub (Solo, Teams, Enterprise) ne sont plus disponibles à l'achat depuis l'arrêt du développement, mais les extensions pour l'IDE restent utilisables gratuitement."}, {"q": "Continue.dev avec des modèles locaux (via Ollama) — quelle est la qualité ?", "a": "Connecter des modèles locaux via Ollama dans Continue.dev convient bien à la complétion de code et aux explications simples, avec une confidentialité totale et un coût nul. Pour la génération de code plus complexe, les modèles cloud (Claude, GPT, etc.) restent généralement supérieurs. À noter que Continue.dev n'est plus activement développé : l'équipe a rejoint Cursor et le dépôt GitHub est désormais en lecture seule."}, {"q": "GitHub Copilot vs Continue.dev — lequel l'emporte ?", "a": "Copilot reste plus mature, avec une meilleure intégration IDE et des performances plus consistantes. Continue.dev offrait plus de flexibilité, la gratuité et le respect de la confidentialité, mais le projet est désormais arrêté en tant que produit autonome : l'équipe a été acqui-hire par Cursor (Anysphere), la version finale v2.0.0 ne recevra plus de mises à jour ni de support, et le dépôt est passé en lecture seule. Pour un outil activement maintenu et tourné vers l'avenir, mieux vaut se tourner vers Copilot, Cursor, ou une autre alternative encore développée."}]$x$::jsonb
 WHERE slug = 'continue-dev' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "O que é o Continue.dev?", "a": "Continue.dev era um assistente de codificação com IA open-source para VS Code e JetBrains, com integração a qualquer LLM (OpenAI, Anthropic, modelos locais via Ollama e outros). Em meados de 2026 a Cursor (Anysphere), dona legal do projeto, acqui-hired a equipe e descontinuou o produto como iniciativa independente. A versão final, v2.0.0, continua disponível e as extensões permanecem gratuitas sob Apache 2.0, mas não recebem mais atualizações."}, {"q": "Continue.dev é realmente gratuito?", "a": "As extensões e a CLI do Continue.dev continuam gratuitas e open-source sob Apache 2.0. O único custo real sempre foi o uso da API do provedor de modelo escolhido (OpenAI, Anthropic etc.), ou zero se você usar modelos locais via Ollama. Os antigos planos pagos do Continue Hub (Solo, Teams, Enterprise) não podem mais ser adquiridos, e a cobrança recorrente foi desativada."}, {"q": "Continue.dev com modelos locais — qual é a qualidade?", "a": "Continue.dev com modelos locais via Ollama funciona bem para autocompletar código e explicações mais simples, mantendo privacidade e custo zero. Para geração de código mais complexa, modelos em nuvem de provedores como OpenAI ou Anthropic tendem a ter desempenho superior. Vale lembrar que, como o projeto está descontinuado e o repositório é somente leitura, não há garantia de novas melhorias ou correções nessa integração."}, {"q": "GitHub Copilot vs Continue.dev — qual ganha?", "a": "O GitHub Copilot é uma ferramenta ativamente mantida, com integração de IDE madura. O Continue.dev, por outro lado, é agnóstico de modelo e gratuito, mas desde a aquisição da equipe pela Cursor em 2026 o projeto está descontinuado: as extensões continuam funcionando e são gratuitas sob Apache 2.0, porém sem novas atualizações, correções ou suporte. Para quem quer uma ferramenta com suporte contínuo, Copilot ou Cursor são as opções recomendadas; para quem prioriza privacidade, uso local e não se importa em usar um projeto arquivado, o Continue.dev ainda é viável."}]$x$::jsonb
 WHERE slug = 'continue-dev' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "What is Cursor?", "a": "Cursor is an AI-native IDE based on VS Code. It gives AI full context of your codebase and can edit multiple files, run terminal commands, and complete tasks end-to-end as an agent."}, {"q": "How much does Cursor cost?", "a": "Cursor has a free Hobby plan. Pro (Individual) is $20/month, Pro+ is $60/month, and Ultra is $200/month. Teams costs $40 per user per month, and Enterprise is custom. Billing is credit-based, with a credit pool roughly equal to the plan price, though Auto mode usage is unlimited on paid plans, and annual billing saves about 20 percent."}, {"q": "Is Cursor safe to use with my codebase?", "a": "The current description doesn't detail specific privacy or compliance features, but Cursor does offer an Enterprise tier with custom terms, which is typically where stricter data controls and team-level governance would be handled."}, {"q": "What models does Cursor use?", "a": "Cursor's flagship model is Composer, its own in-house agentic model, which the company positions as matching frontier models at a fraction of the cost. Cursor also still supports third-party models such as Claude and GPT, and you can switch models per request in settings."}]$x$::jsonb
 WHERE slug = 'cursor' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "¿Zed o VS Code para desarrollo?", "a": "Zed es significativamente más rápido que VS Code — lanzamiento instantáneo, sin lag en archivos grandes. VS Code tiene ecosistema de extensiones mucho mayor. Cursor está basado en VS Code. Para velocidad pura — Zed; para mayor ecosistema — VS Code o Cursor."}, {"q": "¿Zed es gratuito?", "a": "Zed es gratuito y open-source. Las funciones de IA (Zed AI) usan la API de Anthropic o pueden configurarse con otros modelos. Cursor tiene un plan Hobby gratuito; el plan Pro cuesta $20/mes con un sistema de facturación basado en créditos."}, {"q": "¿Zed está disponible en Windows?", "a": "Zed empezó como exclusivo de macOS pero lanzó soporte para Linux. El soporte para Windows está en desarrollo activo pero puede no estar completamente estable. Cursor está disponible en macOS, Windows y Linux."}, {"q": "¿Qué es Cursor Composer?", "a": "Cursor Composer es el agente de Cursor para ediciones grandes — permite describir en lenguaje natural cambios que afectan múltiples archivos simultáneamente y Cursor los implementa, incluso ejecutando su propia revisión del código. Es la diferencia clave frente a otros editores con IA que solo trabajan en el archivo activo. La versión actual, Composer 2.5, es el modelo agéntico desarrollado internamente por Cursor."}, {"q": "¿Qué es Cursor?", "a": "Cursor es un IDE nativo de IA basado en VS Code. Le da al AI contexto completo de tu base de código y puede editar múltiples archivos, ejecutar comandos y completar tareas de principio a fin como agente."}, {"q": "¿Cuánto cuesta Cursor?", "a": "El plan Hobby es gratuito. Pro (Individual) cuesta $20/mes, Pro+ cuesta $60/mes y Ultra cuesta $200/mes. Teams cuesta $40 por usuario al mes, y Enterprise tiene precio personalizado. La facturación es por créditos, con un pool de créditos aproximadamente igual al precio del plan, aunque el uso en modo Auto es ilimitado en los planes de pago. La facturación anual ahorra alrededor de un 20%."}, {"q": "¿Es seguro usar Cursor?", "a": "Cursor ofrece un Modo de Privacidad que deshabilita el almacenamiento de código en sus servidores. Los planes Enterprise incluyen controles adicionales y conformidad SOC 2."}, {"q": "¿Qué modelos usa Cursor?", "a": "Cursor incluye su propio modelo agéntico, Composer, además de permitir usar modelos de terceros como Claude, GPT y Gemini. También soporta MCP servers, reglas personalizadas y hooks, así que no estás limitado a un solo modelo; puedes cambiarlo según la tarea."}]$x$::jsonb
 WHERE slug = 'cursor' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Cursor ist ausgereifter für KI-Coding: stärkere Agenten-Features, Multi-File-Editing und bessere Chat-Integration. Zed ist schneller und hat einzigartige native Multiplayer-Kollaboration. Für KI-Coding — Cursor; für Performance und Zusammenarbeit — Zed.", "q": "Zed vs Cursor: Was ist besser?"}, {"a": "Zed ist kostenlos und Open-Source. KI-Features in Zed nutzen Claude und können API-Kosten verursachen. Cursor hat einen kostenlosen Hobby-Plan mit begrenzten Anfragen; Pro (Individual) kostet $20 pro Monat.", "q": "Ist Zed kostenlos?"}, {"a": "Nein. Zed ist kein VS Code-Fork und verwendet keine VS Code-Extensions. Zed hat sein eigenes Extension-System das wächst aber noch deutlich kleiner als das VS Code-Ökosystem ist.", "q": "Kann Zed VS Code-Extensions verwenden?"}, {"a": "Zed wurde ursprünglich für macOS entwickelt und ist dort am besten optimiert. Es nutzt macOS-native APIs für maximale Performance. Linux-Support ist verfügbar; Windows-Support ist in Entwicklung.", "q": "Zed für macOS: Ist es gut optimiert?"}, {"a": "Cursor ist eine KI-native IDE auf Basis von VS Code. Die KI bekommt vollen Kontext deiner Codebasis, kann mehrere Dateien bearbeiten, Terminal-Befehle ausführen und Aufgaben autonom über Agenten erledigen.", "q": "Was ist Cursor?"}, {"a": "Kostenloser Hobby-Plan mit begrenzten Anfragen. Pro (Individual) kostet $20 pro Monat, Pro+ $60 pro Monat und Ultra $200 pro Monat. Teams kostet $40 pro Nutzer pro Monat, Enterprise ist individuell. Abgerechnet wird über ein Guthaben-System, bei jährlicher Zahlung gibt es rund 20 Prozent Rabatt.", "q": "Was kostet Cursor?"}, {"a": "Cursor bietet einen Datenschutzmodus, der die Code-Speicherung auf ihren Servern deaktiviert. Enterprise-Pläne umfassen zusätzliche Datenkontrolle und SOC 2-Konformität.", "q": "Ist Cursor sicher für meinen Code?"}, {"a": "Cursor setzt vor allem auf sein eigenes Modell Composer, das laut Anbieter mit Spitzenmodellen von Anthropic und OpenAI mithalten soll, dabei aber deutlich günstiger ist. Daneben unterstützt Cursor weiterhin Drittanbieter-Modelle wie Claude und GPT, die sich pro Anfrage in den Einstellungen auswählen lassen.", "q": "Welche Modelle verwendet Cursor?"}]$x$::jsonb
 WHERE slug = 'cursor' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Cursor лучше GitHub Copilot?", "a": "Cursor в целом обеспечивает более мощную ИИ-помощь — контекст всей кодовой базы и многофайловое редактирование в агенте Composer мощнее встроенных подсказок Copilot. Но Copilot поддерживает больше IDE и имеет корпоративные функции. Cursor — выбор для разработчиков, которые хотят более продвинутый агентный ИИ-опыт."}, {"q": "Cursor бесплатный?", "a": "У Cursor есть бесплатный план Hobby с ограниченными возможностями. Платные тарифы для отдельных пользователей: Pro (Individual) — $20 в месяц, Pro+ — $60 в месяц, Ultra — $200 в месяц. Биллинг построен на кредитах, размер пула которых примерно соответствует стоимости тарифа, при этом режим Auto на платных планах не ограничен. Teams стоит $40 за пользователя в месяц, а для Enterprise цена индивидуальная. При годовой оплате есть скидка около 20%."}, {"q": "Cursor использует Claude или GPT?", "a": "Cursor поддерживает несколько сторонних моделей, включая Claude и GPT, а также собственную агентную модель Composer, которую компания разрабатывает и продвигает как альтернативу, сопоставимую по качеству с топовыми моделями индустрии, но заметно дешевле. Пользователи платных тарифов могут выбирать, какую модель использовать под конкретную задачу, не привязываясь только к Composer."}, {"q": "Можно использовать GitHub Copilot и Cursor вместе?", "a": "Да, но их функциональность будет значительно перекрываться. Большинство разработчиков в итоге выбирают один основной инструмент. Cursor обычно предпочтителен за более мощные агентные функции и работу с целым репозиторием, а Copilot остаётся выбором для команд, глубоко завязанных на корпоративные рабочие процессы GitHub."}]$x$::jsonb
 WHERE slug = 'cursor' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Zed vs Cursor — lequel est le meilleur ?", "a": "Cursor est plus mature pour le codage IA : meilleures fonctionnalités agentiques, édition multi-fichiers et meilleure intégration chat. Zed est plus rapide et a une collaboration multiplayer native unique. Pour le codage IA → Cursor ; pour les performances et la collaboration → Zed."}, {"q": "Zed est-il gratuit ?", "a": "Zed est gratuit et open-source. Les fonctionnalités IA dans Zed utilisent Claude et peuvent entraîner des coûts API. Cursor a un plan gratuit avec des requêtes limitées ; Pro à partir de 20 $/mois."}, {"q": "Zed peut-il utiliser des extensions VS Code ?", "a": "Non. Zed n'est pas un fork de VS Code et n'utilise pas les extensions VS Code. Zed a son propre système d'extensions qui croît mais est encore bien plus petit que l'écosystème VS Code."}, {"q": "Zed est-il optimisé pour macOS ?", "a": "Zed a été développé à l'origine pour macOS et y est le mieux optimisé. Il utilise les APIs natives macOS pour des performances maximales. Le support Linux est disponible ; le support Windows est en développement."}, {"q": "Qu'est-ce que Cursor ?", "a": "Cursor est un éditeur de code natif IA, initialement issu d'un fork de VS Code, devenu une plateforme de codage agentique complète. Il donne à l'IA un contexte complet de votre base de code, peut planifier et réaliser des modifications multi-étapes sur plusieurs fichiers, exécuter ses propres passes de revue, et confier du travail à des agents en arrière-plan."}, {"q": "Combien coûte Cursor ?", "a": "Plan Hobby gratuit. Pro (Individual) à 20 $/mois, Pro+ à 60 $/mois, et Ultra à 200 $/mois. Teams coûte 40 $/utilisateur/mois avec des fonctionnalités d'équipe, et Enterprise est sur devis. La facturation fonctionne par crédits, avec un pool de crédits à peu près équivalent au prix du plan ; l'usage en mode Auto est illimité sur les plans payants. La facturation annuelle fait économiser environ 20 %."}, {"q": "Cursor est-il sûr pour mon code ?", "a": "Cursor propose un Mode Confidentialité qui désactive le stockage du code sur leurs serveurs. Les plans Enterprise incluent des contrôles de données supplémentaires et la conformité SOC 2."}, {"q": "Quels modèles utilise Cursor ?", "a": "Cursor utilise des modèles Claude, GPT et d'autres modèles tiers, ainsi que Composer, son propre modèle agentique interne conçu pour offrir une qualité proche des modèles de pointe à un coût nettement inférieur. Vous pouvez changer de modèle par requête dans les paramètres."}]$x$::jsonb
 WHERE slug = 'cursor' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Zed vs Cursor — qual é o melhor?", "a": "Cursor é mais maduro para codificação com IA: melhores funcionalidades agênticas, edição multi-arquivo e melhor integração de chat. Zed é mais rápido e tem colaboração multiplayer nativa única. Para codificação com IA → Cursor; para desempenho e colaboração → Zed."}, {"q": "Zed é gratuito?", "a": "Zed é gratuito e open-source. As funcionalidades de IA no Zed usam Claude e podem ter custos de API. Cursor tem plano gratuito (Hobby) com uso limitado; Pro a partir de $20/mês."}, {"q": "Zed pode usar extensões do VS Code?", "a": "Não. Zed não é um fork do VS Code e não usa extensões do VS Code. Zed tem seu próprio sistema de extensões que está crescendo mas ainda é muito menor que o ecossistema VS Code."}, {"q": "Zed é otimizado para macOS?", "a": "Zed foi desenvolvido originalmente para macOS e está melhor otimizado lá. Usa as APIs nativas do macOS para desempenho máximo. Suporte ao Linux está disponível; suporte ao Windows está em desenvolvimento."}, {"q": "O que é o Cursor?", "a": "O Cursor é um IDE nativo de IA baseado no VS Code. Ele dá à IA contexto completo da sua base de código, pode editar múltiplos arquivos, executar comandos no terminal e completar tarefas do início ao fim como um agente."}, {"q": "Quanto custa o Cursor?", "a": "Plano Hobby é gratuito. Pro (Individual) custa $20/mês, Pro+ custa $60/mês e Ultra custa $200/mês. Teams custa $40 por usuário/mês, e Enterprise tem preço personalizado. A cobrança é baseada em créditos, com um pool aproximadamente igual ao valor do plano; o uso no modo Auto é ilimitado nos planos pagos."}, {"q": "O Cursor é seguro para meu código?", "a": "O Cursor oferece um Modo de Privacidade que desativa o armazenamento de código em seus servidores. Os planos Enterprise incluem controles de dados adicionais e conformidade com SOC 2."}, {"q": "Quais modelos o Cursor usa?", "a": "O Cursor oferece modelos de terceiros como Claude e GPT, além do Composer, o modelo agêntico próprio da Cursor, criado para entregar qualidade próxima aos modelos de ponta por uma fração do custo. Você pode mudar de modelo por solicitação nas configurações."}]$x$::jsonb
 WHERE slug = 'cursor' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "Is DeepSeek better than ChatGPT?", "a": "DeepSeek is a capable assistant for text reasoning, coding, and long-document work, offered through a free web chat and a low-cost, per-token API. It's a strong option if you want an inexpensive way to access capable AI models. ChatGPT has more built-in features (images, voice, plugins) and broader ecosystem support."}, {"q": "Is DeepSeek safe to use?", "a": "DeepSeek is developed by a Chinese AI lab. As a China-based service, it may raise data-residency or compliance questions for some organizations, so it's worth checking your organization's policies before sending sensitive data through the web chat or API."}, {"q": "Is DeepSeek free?", "a": "The web chat at chat.deepseek.com is free to use. The API, however, is a paid, metered service billed per million tokens — for example, the default V4-Flash tier costs $0.14 per million input tokens on a cache miss (as low as $0.0028 on a cache hit) and $0.28 per million output tokens. Some third-party reports of a free token grant for new API accounts are not confirmed in official documentation."}, {"q": "What is DeepSeek's reasoning model?", "a": "DeepSeek's reasoning capability is now part of the current DeepSeek-V4 generation, which replaced the older V3/R1 family. The legacy deepseek-reasoner model name is being deprecated on July 24, 2026 and maps to V4-Flash's thinking mode, which handles chain-of-thought style reasoning tasks."}]$x$::jsonb
 WHERE slug = 'deepseek' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "¿Es DeepSeek tan bueno como ChatGPT?", "a": "DeepSeek-V4, en su versión V4-Pro, está diseñado para competir con los modelos cerrados más avanzados del mercado, con un costo computacional mucho menor gracias a su arquitectura de atención dispersa (DSA). Es una opción sólida para razonamiento y código; en cuanto a ecosistema y funciones adicionales, cada usuario debe evaluar según sus necesidades."}, {"q": "¿DeepSeek es gratuito?", "a": "El acceso web en chat.deepseek.com es gratuito. La API, en cambio, es un servicio pago que cobra por millón de tokens: V4-Flash tiene un costo de 0.14 USD de entrada (0.0028 USD en caso de acierto de caché) y 0.28 USD de salida; V4-Pro cuesta 0.435 USD de entrada (0.003625 USD en caso de acierto de caché) y 0.87 USD de salida."}, {"q": "¿Es DeepSeek seguro para datos de empresa?", "a": "DeepSeek es una empresa china y, como servicio basado en China, puede generar dudas sobre residencia de datos o cumplimiento normativo para algunas organizaciones. Para uso personal resulta práctico, pero muchas empresas con datos sensibles prefieren evaluar cuidadosamente estas implicaciones antes de adoptarlo."}, {"q": "¿Puede DeepSeek programar?", "a": "Sí. DeepSeek-V4 incluye optimizaciones explícitas para tareas agénticas, con integración con herramientas de agentes como Claude Code, además de un contexto de hasta 1M de tokens y salidas de hasta 384K tokens, lo que lo hace apto para trabajo extenso de código y documentos largos."}]$x$::jsonb
 WHERE slug = 'deepseek' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Ist DeepSeek so gut wie ChatGPT?", "a": "DeepSeek-V4 gibt es in zwei Varianten: V4-Pro wurde gezielt entwickelt, um mit führenden Closed-Source-Modellen mitzuhalten, während die günstigere Standardvariante V4-Flash für den Alltag ausgelegt ist. Das Bemerkenswerte sind dabei die vergleichsweise geringen Rechenkosten der API."}, {"q": "Ist DeepSeek kostenlos?", "a": "Teilweise. Der Web-Chat auf chat.deepseek.com ist kostenlos nutzbar. Die API dagegen ist ein kostenpflichtiger, nach Token abgerechneter Dienst, zum Beispiel ab 0,14 US-Dollar pro Million Input-Token bei V4-Flash."}, {"q": "Ist DeepSeek sicher für Unternehmensdaten?", "a": "DeepSeek ist ein chinesisches Unternehmen, weshalb bei manchen Organisationen Fragen zu Datenresidenz oder Compliance aufkommen können. Für den persönlichen Gebrauch ist der kostenlose Web-Zugang praktisch, Unternehmen mit strengen Datenschutzanforderungen sollten den Einsatz aber genauer prüfen."}, {"q": "Kann DeepSeek programmieren?", "a": "Ja. DeepSeek deckt allgemeine Chat-, Programmier-, Reasoning- und Langdokumentaufgaben ab und ist zudem für agentische Workflows optimiert, etwa durch Integration mit Agent-Tools wie Claude Code."}]$x$::jsonb
 WHERE slug = 'deepseek' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "DeepSeek vs ChatGPT — яка різниця?", "a": "DeepSeek — чат-асистент від китайської лабораторії, безкоштовний у веб-інтерфейсі chat.deepseek.com і платний через API з оплатою за токени. Він підходить для загального спілкування, кодування, reasoning та роботи з довгими документами, а також має агентні інтеграції. ChatGPT — закрита модель від OpenAI з ширшою екосистемою готових рішень. DeepSeek приваблює співвідношенням ціни й можливостей API, ChatGPT — зручністю готових інтеграцій."}, {"q": "Чи безпечний DeepSeek?", "a": "DeepSeek — китайська компанія, що викликає питання щодо конфіденційності даних, зокрема через можливі вимоги до резидентності даних для деяких організацій. Корпоративні та чутливі дані вводити в DeepSeek API варто обережно. Офіційна документація не підтверджує деякі сторонні звіти про безкоштовні токени для нових акаунтів, тож перед використанням варто перевіряти умови напряму на сайті."}, {"q": "DeepSeek чи ChatGPT для кодування?", "a": "DeepSeek підтримує кодування, reasoning і роботу з великим контекстом (до 1M токенів на вхід і до 384K на вихід), а також інтегрується з агентними інструментами на кшталт Claude Code. Його API дешевший за оплатою за токени порівняно з готовими рішеннями. ChatGPT пропонує ширшу екосистему готових інтеграцій. Конкретний вибір варто робити на основі вартості API та потрібних інтеграцій, а не застарілих бенчмарків."}]$x$::jsonb
 WHERE slug = 'deepseek' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "DeepSeek מול ChatGPT — מה ההבדל?", "a": "DeepSeek הוא עוזר שיחה סיני, כיום בגרסת DeepSeek-V4, הזמין בחינם דרך ממשק הצ'אט וגם כ-API בתשלום לפי טוקן. ChatGPT הוא מודל אמריקאי סגור מ-OpenAI עם מערכת-אקולוגית רחבה יותר. DeepSeek עדיף ביחס עלות/ביצועים בזכות תמחור API נמוך; ChatGPT עדיף לפתרונות מוכנים ואינטגרציות מבוססות."}, {"q": "האם DeepSeek בטוח?", "a": "DeepSeek היא חברה סינית, מה שמעלה שאלות לגבי פרטיות הנתונים. לא מומלץ להזין נתונים ארגוניים או רגישים ב-DeepSeek API. לשימוש פרטי — פרסו מקומית דרך Ollama."}, {"q": "DeepSeek או ChatGPT לקוד?", "a": "DeepSeek-V4 כולל יכולות קידוד וחשיבה, חלון הקשר רחב, ואופטימיזציה לעבודה עם כלים אגנטיים כמו Claude Code, לצד תמחור API נמוך משמעותית. ChatGPT נוח יותר לאינטגרציית IDE דרך GitHub Copilot. הבחירה תלויה בתקציב ובצורך באינטגרציה קיימת."}]$x$::jsonb
 WHERE slug = 'deepseek' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "DeepSeek vs ChatGPT — quelle est la différence ?", "a": "DeepSeek est un assistant IA chinois accessible gratuitement via son interface web (chat.deepseek.com) et via une API payante facturée au token. ChatGPT est un service fermé américain d'OpenAI, avec un écosystème plus large. DeepSeek se distingue par son rapport qualité-prix ; ChatGPT propose des solutions plus intégrées et clé en main."}, {"q": "DeepSeek est-il sûr ?", "a": "DeepSeek est une société chinoise, ce qui peut soulever des questions de résidence des données et de conformité pour certaines organisations. Il est déconseillé d'entrer des données d'entreprise sensibles dans l'API DeepSeek si ces questions sont critiques pour votre usage."}, {"q": "DeepSeek est-il vraiment gratuit ?", "a": "L'interface web DeepSeek Chat (chat.deepseek.com) est gratuite. L'API, elle, est payante et facturée par million de tokens, avec des tarifs différents selon le modèle (V4-Flash ou V4-Pro) et selon qu'il s'agit d'un cache hit ou miss."}, {"q": "DeepSeek ou ChatGPT pour le codage ?", "a": "DeepSeek propose un modèle optimisé pour la conversation générale, le code, le raisonnement et le traitement de documents longs, avec des optimisations agentiques et une intégration à des outils comme Claude Code. La description actuelle ne fournit pas de comparaison chiffrée avec ChatGPT pour le codage ; le choix dépendra donc surtout du coût, via l'API DeepSeek facturée au token, et de vos besoins d'intégration."}]$x$::jsonb
 WHERE slug = 'deepseek' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "DeepSeek vs ChatGPT — qual é a diferença?", "a": "DeepSeek é um assistente de IA chinês que pode ser usado gratuitamente pelo chat web e também via API paga, cobrada por token. ChatGPT é um assistente da OpenAI, empresa americana, com um ecossistema maior de integrações. Em termos de custo, a API do DeepSeek tende a ser mais barata; o ChatGPT costuma ser a opção mais conveniente para quem já usa o ecossistema da OpenAI."}, {"q": "DeepSeek é seguro?", "a": "DeepSeek é uma empresa chinesa, o que pode levantar questões de residência de dados e conformidade para algumas organizações. Por isso, é recomendável avaliar as políticas internas da sua empresa antes de enviar dados corporativos sensíveis pela API do DeepSeek."}, {"q": "DeepSeek é realmente gratuito?", "a": "O chat web em chat.deepseek.com (DeepSeek Chat) é gratuito. Já a API é paga, cobrada por milhão de tokens, com valores diferentes para os planos V4-Flash e V4-Pro, mas geralmente mais baratos que os de outros grandes provedores."}, {"q": "DeepSeek ou ChatGPT para programação?", "a": "O DeepSeek atual lida com chat geral, programação, raciocínio e trabalho com documentos longos, além de contar com otimizações agentivas, incluindo integração com ferramentas de agente como o Claude Code. Para codificação, o DeepSeek costuma ser mais econômico via API; o ChatGPT pode ser mais conveniente para quem já depende do ecossistema de integrações da OpenAI."}]$x$::jsonb
 WHERE slug = 'deepseek' AND lang = 'pt';

UPDATE tools SET pros = ARRAY[$x$Video Call offers live spoken practice with an AI character that remembers earlier sessions$x$, $x$Roleplay scenarios let you rehearse realistic situations at your own pace, judgment-free$x$, $x$Built on OpenAI's current GPT models for more natural conversational responses$x$, $x$Ad-free access to the full Duolingo course catalog$x$, $x$Lower-pressure speaking practice than a live human tutor for nervous beginners$x$]::text[]
 WHERE slug = 'duolingo-max' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "What is Duolingo Max?", "a": "Duolingo Max is the premium tier of Duolingo that adds AI features powered by current GPT models. Its key capabilities are Video Call, a live spoken conversation with an animated character named Lily who remembers details across sessions, and Roleplay, practice conversations with AI characters in real-life scenarios. Note that 'Explain My Answer' is no longer a Max exclusive and is now free for all Duolingo users."}, {"q": "Can Duolingo teach me to be fluent?", "a": "Duolingo builds vocabulary and basic grammar effectively but is generally not sufficient to reach fluency alone. It works best as a daily habit combined with other practice like speaking with native speakers, watching content, or using tools like iTalki for conversation practice."}]$x$::jsonb
 WHERE slug = 'duolingo-max' AND lang = 'en';

UPDATE tools SET pros = ARRAY[$x$Video Call ofrece práctica hablada en vivo con un personaje de IA que recuerda sesiones anteriores$x$, $x$Los escenarios de Roleplay permiten ensayar situaciones reales a tu ritmo y sin juicios$x$, $x$Basado en los modelos GPT de OpenAI para respuestas conversacionales más naturales$x$, $x$Acceso sin anuncios a todo el catálogo de cursos de Duolingo$x$, $x$Práctica oral con menos presión que con un profesor humano, ideal para principiantes tímidos$x$]::text[]
 WHERE slug = 'duolingo-max' AND lang = 'es';

UPDATE tools SET pros = ARRAY[$x$Video Call bietet gesprochene Live-Übungen mit einer KI-Figur, die sich frühere Sitzungen merkt$x$, $x$Roleplay-Szenarien lassen realistische Situationen im eigenen Tempo und ohne Bewertung üben$x$, $x$Läuft mittlerweile auf OpenAIs GPT-5.6 für natürlichere Gesprächsantworten$x$, $x$Werbefreier Zugang zum kompletten Duolingo-Kurskatalog$x$, $x$Sprechpraxis mit weniger Druck als bei einem menschlichen Lehrer, gut für schüchterne Anfänger$x$]::text[]
 WHERE slug = 'duolingo-max' AND lang = 'de';

UPDATE tools SET pros = ARRAY[$x$Video Call даёт живую голосовую практику с ИИ-персонажем, который помнит прошлые беседы$x$, $x$Сценарии Roleplay позволяют отрабатывать реальные ситуации в своём темпе и без осуждения$x$, $x$Построен на актуальных моделях GPT от OpenAI (сейчас — GPT-5.6), что делает ответы более естественными$x$, $x$Полный каталог курсов Duolingo без рекламы$x$, $x$Разговорная практика с меньшим стрессом, чем с живым репетитором — плюс для стеснительных новичков$x$]::text[]
 WHERE slug = 'duolingo-max' AND lang = 'ru';

UPDATE tools SET pros = ARRAY[$x$Video Call дає живу голосову практику зі ШІ-персонажем, який пам'ятає попередні бесіди$x$, $x$Сценарії Roleplay дозволяють відпрацьовувати реальні ситуації у своєму темпі й без осуду$x$, $x$Побудований на актуальних GPT-моделях від OpenAI, що робить відповіді природнішими$x$, $x$Повний каталог курсів Duolingo без реклами$x$, $x$Розмовна практика з меншим стресом, ніж із живим репетитором — плюс для сором'язливих початківців$x$]::text[]
 WHERE slug = 'duolingo-max' AND lang = 'ua';

UPDATE tools SET pros = ARRAY[$x$Video Call מציע תרגול קולי חי עם דמות AI שזוכרת מפגשים קודמים$x$, $x$תרחישי Roleplay מאפשרים לתרגל מצבים מציאותיים בקצב שלכם וללא שיפוטיות$x$, $x$מבוסס על מודלי GPT העדכניים של OpenAI לתגובות שיחה טבעיות יותר$x$, $x$גישה ללא פרסומות לכל קטלוג הקורסים של Duolingo$x$, $x$תרגול דיבור בלחץ נמוך יותר מאשר מול מורה אנושי, יתרון למתחילים ביישנים$x$]::text[]
 WHERE slug = 'duolingo-max' AND lang = 'he';

UPDATE tools SET pros = ARRAY[$x$Video Call offre une pratique orale en direct avec un personnage IA qui se souvient des sessions passées$x$, $x$Les scénarios Roleplay permettent de répéter des situations réalistes à son rythme et sans jugement$x$, $x$Reposant sur les modèles GPT d'OpenAI pour des réponses conversationnelles plus naturelles$x$, $x$Accès sans publicité à l'ensemble du catalogue de cours Duolingo$x$, $x$Pratique orale moins stressante qu'avec un professeur humain, idéale pour les débutants timides$x$]::text[]
 WHERE slug = 'duolingo-max' AND lang = 'fr';

UPDATE tools SET pros = ARRAY[$x$O Video Call oferece prática falada ao vivo com uma personagem de IA que lembra sessões anteriores$x$, $x$Os cenários de Roleplay permitem ensaiar situações realistas no seu ritmo e sem julgamentos$x$, $x$Atualmente reportado como baseado no GPT-5.6 da OpenAI para respostas de conversa mais naturais$x$, $x$Acesso sem anúncios a todo o catálogo de cursos do Duolingo$x$, $x$Prática oral com menos pressão do que com um professor humano, ideal para iniciantes tímidos$x$]::text[]
 WHERE slug = 'duolingo-max' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "Is Gemini better than ChatGPT?", "a": "On Google Workspace tasks, Gemini's deep integration with Gmail, Docs and Sheets makes it the more convenient choice. General capability comparisons with other assistants shift too often to declare a lasting winner. Gemini is the strongest fit for people already inside Google's ecosystem, while other assistants may appeal more for general use depending on their own feature sets."}, {"q": "Is Gemini free?", "a": "Yes. The free tier includes Gemini 3.8 Flash, limited daily access to Gemini 3.1 Pro, image and video generation, Deep Research and Gemini Live. Paid plans add more: Google AI Plus is $7.99/month, Google AI Pro is $19.99/month with higher limits and 2TB storage, and Google AI Ultra now spans a $100/month entry tier and a $200/month top tier for the most demanding use."}, {"q": "Can Gemini generate images?", "a": "Yes. Gemini includes native image and video generation alongside its chat, coding and Deep Research capabilities. It's convenient for quick, integrated creation within the Google ecosystem rather than needing a separate tool."}, {"q": "What is the difference between Gemini and Google Bard?", "a": "Bard was Google's original AI chatbot, rebranded as Gemini in February 2024. They are the same product — if you used Bard, you're now using Gemini. The rebrand accompanied a significant upgrade in model capabilities."}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "¿Gemini es mejor que ChatGPT?", "a": "Depende del caso de uso. Gemini ofrece contexto muy amplio y se integra nativamente con Google Workspace (Gmail, Docs, Sheets). ChatGPT tiene su propio ecosistema y modelos de OpenAI. Para usuarios de Google, Gemini es la opción más natural; para otros ecosistemas, ChatGPT puede ser preferible."}, {"q": "¿Gemini es gratuito?", "a": "Sí. Existe un plan gratuito que incluye Gemini 3.8 Flash, acceso diario limitado a Gemini 3.1 Pro, generación de imagen y video, Deep Research y Gemini Live. Google AI Plus cuesta $7.99/mes y Google AI Pro (antes Google One AI Premium) cuesta $19.99/mes, con mayores límites y 2TB de almacenamiento."}, {"q": "¿Puede Gemini generar imágenes?", "a": "Sí. Gemini puede generar imágenes y video de forma nativa, y los planes de pago desbloquean mayores capacidades. ChatGPT, por su parte, usa los modelos de generación de imágenes de OpenAI."}, {"q": "¿Cuál es la diferencia entre Gemini y Google Bard?", "a": "Google Bard fue renombrado a Gemini en febrero de 2024. Gemini es el sucesor directo, con modelos mucho más potentes: hoy el modelo por defecto es Gemini 3.8 Flash y el buque insignia para razonamiento y programación es Gemini 3.1 Pro."}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Ist Gemini besser als ChatGPT?", "a": "Es hängt vom Anwendungsfall ab. Gemini ist nativ in Google Workspace integriert und kann über sehr lange Kontexte hinweg arbeiten, was sich für große Codebasen und lange Dokumente eignet. ChatGPT hat ein breiteres Plugin-Ökosystem und eigene Bildgenerierung. Für Google-Nutzer — Gemini; für das breiteste Ökosystem — ChatGPT."}, {"q": "Ist Gemini kostenlos?", "a": "Ja. Der kostenlose Plan umfasst Gemini 3.8 Flash, einen begrenzten täglichen Zugang zu Gemini 3.1 Pro sowie Bild- und Videogenerierung, Deep Research und Gemini Live. Kostenpflichtig sind Google AI Plus (7,99 $/Monat), Google AI Pro (19,99 $/Monat, mit 2TB Speicher und höheren Limits) sowie Google AI Ultra, das inzwischen in zwei Stufen für 100 $ bzw. 200 $ pro Monat angeboten wird."}, {"q": "Kann Gemini Bilder generieren?", "a": "Ja. Gemini kann nativ Bilder und Videos erzeugen und bearbeiten, unter anderem über Gemini Omni. Kostenpflichtige Pläne schalten höhere Limits und Zusatzfunktionen frei. ChatGPT nutzt dafür die Bildmodelle von OpenAI."}, {"q": "Was ist der Unterschied zwischen Gemini und Google Bard?", "a": "Google Bard wurde im Februar 2024 in Gemini umbenannt. Gemini ist der direkte Nachfolger mit deutlich leistungsfähigeren Modellen, darunter das aktuelle Flaggschiff Gemini 3.1 Pro für anspruchsvolles Reasoning und Coding sowie Gemini 3.8 Flash als Standardmodell."}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'de';

UPDATE tools SET faq = $x$[{"a": "Прямое сравнение зависит от задачи. Gemini выделяется глубокой интеграцией с Google Workspace (Gmail, Docs, Sheets), встроенной генерацией изображений и видео, а также функцией Deep Research для многоисточниковых отчётов и Gemini Live для голосового общения в реальном времени. Для пользователей, уже живущих в экосистеме Google, Gemini обычно удобнее; для универсального использования ChatGPT остаётся хорошей альтернативой.", "q": "Gemini лучше ChatGPT?"}, {"a": "Да. Бесплатный тариф включает Gemini 3.8 Flash, ограниченный дневной доступ к Gemini 3.1 Pro, генерацию изображений и видео, Deep Research и Gemini Live. Google AI Pro за $19.99/мес снимает часть ограничений, добавляет 2 ТБ хранилища и повышенные лимиты; есть также план Google AI Plus за $7.99/мес и два уровня Google AI Ultra — за $100/мес и $200/мес — с максимальными возможностями.", "q": "Gemini бесплатный?"}, {"a": "Bard — исходное название ИИ-чатбота Google, переименованного в Gemini в феврале 2024 года. Это один и тот же продукт — ребрендинг сопровождался значительным улучшением возможностей модели.", "q": "В чём разница между Gemini и Google Bard?"}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Gemini чи ChatGPT — що краще?", "a": "Для користувачів Google Workspace — Gemini, оскільки він глибоко інтегрований у Gmail, Docs і Sheets і поєднує чат, генерацію зображень і відео, Deep Research та Gemini Live в одному місці. Для кодування та складних задач відповідає флагманська модель Gemini 3.1 Pro, а за агентну роботу й повсякденні запити відповідає Gemini 3.8 Flash."}, {"q": "Чи безкоштовний Gemini?", "a": "Так, є безкоштовний тариф, який включає Gemini 3.8 Flash, обмежений щоденний доступ до Gemini 3.1 Pro, генерацію зображень і відео, Deep Research та Gemini Live. Платні плани — Google AI Plus за $7.99/міс, Google AI Pro за $19.99/міс (з 2 ТБ сховища й вищими лімітами) та Google AI Ultra у двох рівнях — $100/міс і $200/міс."}, {"q": "Чим відрізняється Gemini від Google Bard?", "a": "Bard — це попередня назва продукту, яку Google замінив на Gemini разом з оновленням моделей. Сьогодні флагманською моделлю лінійки є Gemini 3.1 Pro для складних задач, а Gemini 3.8 Flash за замовчуванням обробляє агентну й повсякденну роботу, тож можливості значно перевищують оригінальний Bard."}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Gemini או ChatGPT — מה עדיף?", "a": "למשתמשי Google Workspace — Gemini, כי הוא משולב ב-Gmail, Docs ו-Sheets. ChatGPT מציע מערכת-אקולוגית גדולה יותר לשימוש כללי. לקוד ולמשימות הסקה כבדות, Gemini 3.1 Pro משמש כדגל הנוכחי של גוגל, בזמן ש-Gemini 3.8 Flash מוביל במשימות סוכן ארוכות-טווח."}, {"q": "האם Gemini בחינם?", "a": "כן, יש שכבה חינמית הכוללת את Gemini 3.8 Flash וגישה יומית מוגבלת ל-Gemini 3.1 Pro, בנוסף ליצירת תמונות ווידאו, Deep Research ו-Gemini Live. השכבות בתשלום הן Google AI Plus ב-7.99$/חודש, Google AI Pro ב-19.99$/חודש (מה שהיה Gemini Advanced, עם 2TB אחסון), ו-Google AI Ultra בשתי דרגות: 100$/חודש ו-200$/חודש."}, {"q": "מה ההבדל בין Gemini ל-Google Bard?", "a": "Bard הוא השם הישן. Google שינתה את השם ל-Gemini בפברואר 2024 יחד עם עדכון המודלים. הדגמים הנוכחיים, כמו Gemini 3.8 Flash ו-Gemini 3.1 Pro, חזקים בהרבה מהגרסה המקורית של Bard."}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Gemini ou ChatGPT — lequel est le meilleur ?", "a": "Pour les utilisateurs de Google Workspace, Gemini est intégré dans Gmail, Docs et Drive. Pour une utilisation générale, ChatGPT dispose d'un plus grand écosystème. Pour le codage, les deux sont puissants ; le modèle phare de Gemini est conçu pour les tâches de raisonnement et de codage les plus exigeantes."}, {"q": "Gemini est-il gratuit ?", "a": "Oui, Gemini propose un vrai niveau gratuit incluant Gemini 3.8 Flash, un accès quotidien limité au modèle phare, la génération d'images et de vidéos, Deep Research et Gemini Live. Pour aller plus loin, Google propose Google AI Plus à 7,99 $/mois et Google AI Pro à 19,99 $/mois (l'ancien Gemini Advanced), avec des formules Ultra plus coûteuses pour les usages intensifs. ChatGPT propose aussi une version gratuite et un abonnement payant."}, {"q": "Quelle est la différence entre Gemini et Google Bard ?", "a": "Bard est l'ancien nom. Google l'a renommé Gemini en février 2024 avec des mises à jour de modèles. Le Gemini actuel est nettement plus puissant que le Bard original."}, {"q": "Gemini est-il adapté aux étudiants ?", "a": "Oui. Gemini est gratuit et s'intègre bien avec Google Docs pour la rédaction et la recherche. Pour les étudiants utilisant Google Workspace, c'est un choix pratique. NotebookLM (aussi de Google) est excellent pour travailler avec des sources et des notes."}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Gemini ou ChatGPT — qual é o melhor?", "a": "Para usuários do Google Workspace, o Gemini está integrado ao Gmail, Docs e Drive. Para uso geral, o ChatGPT tem um ecossistema maior. Para programação, o Gemini 3.1 Pro é o modelo mais avançado do Google, voltado para raciocínio e código mais pesados, enquanto o Gemini 3.8 Flash lida bem com tarefas de agente de longo prazo."}, {"q": "Gemini é gratuito?", "a": "Sim, o Gemini tem um tier gratuito que inclui o Gemini 3.8 Flash, acesso diário limitado ao Gemini 3.1 Pro, geração de imagem e vídeo, Deep Research e Gemini Live. Para mais recursos, há o Google AI Plus por $7,99/mês, o Google AI Pro por $19,99/mês (que substituiu o antigo Gemini Advanced / Google One AI Premium, com 2TB de armazenamento) e o Google AI Ultra, a partir de $100/mês."}, {"q": "Qual é a diferença entre Gemini e Google Bard?", "a": "Bard era o nome antigo. O Google o renomeou para Gemini em fevereiro de 2024 com atualizações de modelo. Os modelos atuais, como o Gemini 3.8 Flash e o Gemini 3.1 Pro, são significativamente mais poderosos do que o Bard original."}, {"q": "Gemini é adequado para estudantes?", "a": "Sim. Gemini é gratuito e se integra bem com o Google Docs para redação e pesquisa. Para estudantes usando o Google Workspace, é uma escolha prática. NotebookLM (também do Google) é excelente para trabalhar com fontes e notas."}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "What is Grok AI?", "a": "Grok is xAI's AI assistant built into X (Twitter) and also available as a standalone product at grok.com. It has real-time access to X posts and trending topics, making it unique for social media intelligence. The current flagship is Grok 4.5, which carries a large context window and a recent knowledge cutoff."}, {"q": "Is Grok free?", "a": "Grok offers a free tier that runs a lighter Grok 4 Mini, text only, capped at roughly 10 prompts every 2 hours; image and video generation are not included. Paid options include X Premium at $8/month, SuperGrok Lite at $10/month, SuperGrok at $30/month (or $300/year, about 17% off), X Premium+ at $40/month, and SuperGrok Heavy at $300/month. Getting the full flagship experience and Grok Imagine requires a paid plan."}, {"q": "Is Grok better than ChatGPT?", "a": "The card doesn't provide a head-to-head benchmark comparison between Grok and other assistants. Grok's main differentiators are its real-time access to X/Twitter posts, its more candid and opinionated conversational style, and a competitively priced API for developers."}, {"q": "Does Grok generate images?", "a": "Yes. Grok includes Grok Imagine for image and video generation, comparable to OpenAI's image models. Note that image and video generation were removed from the free tier, so a paid plan is required to use them."}]$x$::jsonb
 WHERE slug = 'grok' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "Что такое Grok AI?", "a": "Grok — ИИ-ассистент от xAI, компании Илона Маска. Работает внутри X (Twitter) и как отдельный продукт на grok.com. Имеет доступ в реальном времени к постам и трендовым темам X, что уникально для разведки в соцсетях, а также более раскованный, непосредственный стиль общения, чем у большинства конкурентов. Текущий флагман — Grok 4.5, доступный через планы SuperGrok, а также встроенный в сторонние инструменты, например GitHub Copilot."}, {"q": "Grok бесплатный?", "a": "Есть бесплатный уровень ($0), но он ограничен: работает только текстовая облегчённая модель Grok 4 Mini с лимитом около 10 запросов каждые 2 часа, без генерации изображений и видео. Платные варианты включают X Premium ($8/мес), SuperGrok Lite ($10/мес), SuperGrok ($30/мес или $300/год), X Premium+ ($40/мес) и SuperGrok Heavy ($300/мес). Полный доступ к флагманской модели и генерации через Grok Imagine требует платного плана."}, {"q": "Grok лучше ChatGPT?", "a": "В карточке нет прямых сравнительных бенчмарков Grok с моделями других компаний, поэтому однозначно сказать нельзя. Главные отличия Grok — тесная интеграция с X и доступ к постам в реальном времени, более раскованный тон общения и конкурентную цену API. Grok поддерживает текстовый чат, понимание изображений и видео, поиск по вебу и X, а также генерацию изображений и видео через Grok Imagine."}]$x$::jsonb
 WHERE slug = 'grok' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Grok vs ChatGPT — яка різниця?", "a": "Grok від xAI має реальний доступ до X і є менш обмеженим. ChatGPT від OpenAI має кращу екосистему і є стандартом галузі. Для X-даних і менших обмежень — Grok; для роботи і розробки — ChatGPT."}, {"q": "Скільки коштує Grok?", "a": "Grok пропонує кілька рівнів доступу: безкоштовний тариф з обмеженнями (лише текст, приблизно 10 запитів кожні 2 години), X Premium за $8/міс, SuperGrok Lite за $10/міс, SuperGrok за $30/міс (або $300/рік зі знижкою близько 17%), X Premium+ за $40/міс та SuperGrok Heavy за $300/міс. Для розробників доступний API за $1.25 за мільйон вхідних токенів і $2.50 за мільйон вихідних."}, {"q": "Чи Grok сильніший за ChatGPT у складних задачах?", "a": "У картці немає конкретних результатів тестів, що порівнюють Grok із ChatGPT. Обидва належать до провідних розробників — xAI та OpenAI — і пропонують потужні флагманські моделі. Найбільша перевага Grok полягає в тісній інтеграції з X і доступі до актуальних постів у реальному часі, тоді як ChatGPT відомий розвиненою екосистемою та широким набором інтеграцій."}]$x$::jsonb
 WHERE slug = 'grok' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Grok מול ChatGPT — מה ההבדל?", "a": "Grok מבית xAI מציע גישה בזמן אמת לפוסטים ב-X וסגנון שיח פתוח וחצוף יותר מרוב המתחרים. ChatGPT מבית OpenAI נשען על מערכת-אקולוגית רחבה ונחשב לסטנדרט מוכר בתעשייה. לנתוני X עדכניים וטון ישיר — Grok; לעבודה ופיתוח סטנדרטיים — ChatGPT."}, {"q": "כמה עולה Grok?", "a": "Grok זמין בחינם (מריץ את Grok 4 Mini, טקסט בלבד, עד כ-10 בקשות ב-2 שעות), וכן במסלולי X Premium (8$/חודש), SuperGrok Lite (10$/חודש), SuperGrok (30$/חודש או 300$/שנה, חיסכון של כ-17%), X Premium+ (40$/חודש) ו-SuperGrok Heavy (300$/חודש). ה-API של Grok מתומחר ב-1.25$ למיליון טוקני קלט ו-2.50$ למיליון טוקני פלט."}, {"q": "האם Grok טוב יותר מ-ChatGPT?", "a": "אין השוואת בנצ'מארק ישירה בין השניים במסגרת המידע הקיים. הדגל הנוכחי של Grok, Grok 4.5, מוצג על ידי xAI כמודל מסוג 'Opus-class' עם חלון קונטקסט גדול, וזמין למי שמעל למסלול חינמי. היתרון הבולט של Grok נשאר הגישה בזמן אמת לנתוני X — למי שצריך את זה, Grok עדיף; לצרכים כלליים ההבדל בין הכלים תלוי בשימוש הספציפי."}]$x$::jsonb
 WHERE slug = 'grok' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Grok vs ChatGPT — quelle est la différence ?", "a": "Grok de xAI a un accès réel à X et est moins restrictif. ChatGPT d'OpenAI a un meilleur écosystème et est la référence du secteur. Pour les données X et moins de restrictions, Grok ; pour le travail et le développement, ChatGPT."}, {"q": "Combien coûte Grok ?", "a": "Grok propose un palier gratuit limité (Grok 4 Mini, texte uniquement, environ 10 messages toutes les 2 heures), ainsi que plusieurs offres payantes : X Premium à 8 $/mois, SuperGrok Lite à 10 $/mois, SuperGrok à 30 $/mois (ou 300 $/an, soit environ 17 % de réduction), X Premium+ à 40 $/mois, et SuperGrok Heavy à 300 $/mois. L'accès via l'API xAI coûte 1,25 $ par million de tokens en entrée et 2,50 $ par million de tokens en sortie."}, {"q": "Grok vs ChatGPT — lequel est le plus puissant ?", "a": "Le modèle phare actuel de Grok est Grok 4.5, doté d'une fenêtre de contexte de 500k tokens. La description ne fournit pas de comparaison chiffrée avec ChatGPT, mais Grok conserve un avantage net sur l'accès en temps réel aux données de X, ce que la plupart des rivaux n'offrent pas nativement."}, {"q": "Grok est-il non censuré ?", "a": "Grok est moins restrictif que ChatGPT sur certains sujets, avec un ton plus libre et plus tranché. Mais il n'est pas entièrement non censuré : xAI applique ses propres limites de sécurité."}]$x$::jsonb
 WHERE slug = 'grok' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Grok vs ChatGPT — qual é a diferença?", "a": "Grok, da xAI, tem acesso real a posts do X e um estilo mais solto e opinativo. ChatGPT, da OpenAI, tem um ecossistema mais amplo e é a referência do setor. Para dados do X e um tom menos comedido, Grok; para trabalho e desenvolvimento em geral, ChatGPT."}, {"q": "Quanto custa o Grok?", "a": "O plano gratuito é $0, mas roda apenas o Grok 4 Mini, só texto, com limite de cerca de 10 prompts a cada 2 horas. Os planos pagos incluem X Premium ($8/mês), SuperGrok Lite ($10/mês), SuperGrok ($30/mês ou $300/ano, cerca de 17% de desconto), X Premium+ ($40/mês) e SuperGrok Heavy ($300/mês). Para o modelo principal completo e o Grok Imagine é preciso um plano pago."}, {"q": "Grok é mais poderoso que o ChatGPT?", "a": "Não há dados de benchmark comparando diretamente os dois no momento. O que se sabe é que o Grok atual, o Grok 4.5, traz uma janela de contexto de 500 mil tokens e conhecimento atualizado até fevereiro de 2026, além de vantagem em acesso a dados em tempo real do X, algo que o ChatGPT não oferece."}, {"q": "Grok não tem censura?", "a": "Grok é menos restritivo que o ChatGPT em certos tópicos, com um estilo de conversa mais solto e opinativo. Mas não é totalmente sem censura: a xAI mantém seus próprios limites de segurança."}]$x$::jsonb
 WHERE slug = 'grok' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "What is Meta AI?", "a": "Meta AI is Meta's assistant built into WhatsApp, Instagram, Facebook, Messenger and Threads, plus Meta's AI glasses. As of April 2026 it runs on Muse Spark, Meta Superintelligence Labs' first proprietary model. It can answer questions, draft and rewrite text, summarize threads, help in group chats, and generate images through Muse Image — all without leaving Meta's apps. A free tier is available, alongside newer paid Meta One plans."}, {"q": "Is Meta AI free?", "a": "A free tier still exists for casual use, but Meta AI is no longer fully free. In May/June 2026 Meta introduced paid subscriptions under the Meta One brand: consumer plans are Meta One Plus at $7.99/month and Meta One Premium at $19.99/month, with business plans at $14.99/month (Essential) and $49.99/month (Advanced). Paid tiers began testing in Singapore, Guatemala and Bolivia and are expanding to more countries."}, {"q": "Is Meta AI as good as ChatGPT?", "a": "Meta AI now runs on Muse Spark, Meta Superintelligence Labs' first proprietary model, replacing the earlier Llama-based engine. It's built for everyday conversation, drafting, summarizing and image generation directly inside Meta's apps, which makes it convenient if you already live in WhatsApp, Instagram or Messenger. There's no official benchmark comparison to other assistants in the current description, so it's best evaluated on convenience and integration rather than raw model performance."}, {"q": "Can Meta AI generate images?", "a": "Yes. Since July 2026, Meta AI generates images using Muse Image, Meta's first in-house image-generation model. It works directly within apps like Instagram and WhatsApp, making it convenient for casual, in-context image creation."}]$x$::jsonb
 WHERE slug = 'meta-ai' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "¿Meta AI es gratuito?", "a": "Meta AI mantiene un nivel gratuito para uso casual en WhatsApp, Instagram, Facebook, Messenger y Threads. Sin embargo, desde mediados de 2026 Meta introdujo suscripciones de pago bajo la marca Meta One (Plus, Premium para consumidores; Essential, Advanced para empresas) que desbloquean funciones adicionales. Los planes pagos se están expandiendo país por país, así que la disponibilidad puede variar."}, {"q": "¿Qué modelo usa Meta AI?", "a": "Desde abril de 2026 Meta AI funciona con Muse Spark, el primer modelo propietario de Meta Superintelligence Labs, que reemplazó al motor anterior basado en Llama. Este cambio fue controvertido porque alejó a Meta de su enfoque de pesos abiertos. En julio de 2026 se sumó Muse Image, el primer modelo propio de Meta para generación de imágenes."}, {"q": "¿Puede Meta AI ver mis fotos de Instagram?", "a": "Meta AI puede analizar fotos que compartas en la conversación, pero no accede automáticamente a tu galería. Solo procesa lo que compartes directamente en el chat."}, {"q": "¿Meta AI vs ChatGPT: cuál es mejor para estudiantes?", "a": "ChatGPT es más versátil para estudios — análisis de documentos, ayuda con código, intérprete matemático. Meta AI es conveniente por estar directamente en WhatsApp (sin instalar nada extra) y mantiene un nivel gratuito, aunque desde 2026 también ofrece planes de pago Meta One con funciones adicionales. Para tareas académicas profundas, ChatGPT Plus ofrece más herramientas."}]$x$::jsonb
 WHERE slug = 'meta-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Meta AI bietet weiterhin eine kostenlose Stufe für den alltäglichen Gebrauch, ist aber nicht mehr vollständig kostenlos. Seit Mai/Juni 2026 hat Meta bezahlte Abonnements unter der Marke Meta One eingeführt: für Privatnutzer Meta One Plus (7,99 $/Monat) und Meta One Premium (19,99 $/Monat), für Unternehmen Meta One Essential (14,99 $/Monat) und Meta One Advanced (49,99 $/Monat). Der bezahlte Test begann im Juni 2026 in Singapur, Guatemala und Bolivien und wird schrittweise weltweit ausgeweitet.", "q": "Ist Meta AI kostenlos?"}, {"a": "Meta AI wird nicht mehr von Llama 4 angetrieben. Seit der Ankündigung vom 8. April 2026 läuft es auf Muse Spark, dem ersten proprietären Sprachmodell der Meta Superintelligence Labs — ein bemerkenswerter und umstrittener Schritt weg von Metas offener Llama-Reihe. Im Juli 2026 kam mit Muse Image zudem Metas erstes hauseigenes Bildgenerierungsmodell hinzu.", "q": "Welches Modell verwendet Meta AI?"}, {"a": "Meta AI kann Fotos analysieren, die Sie im Gespräch teilen, greift aber nicht automatisch auf Ihre Galerie zu. Es verarbeitet nur, was Sie direkt im Chat teilen.", "q": "Kann Meta AI meine Instagram-Fotos sehen?"}, {"a": "ChatGPT bietet vielseitige Werkzeuge fürs Studium. Meta AI punktet dagegen damit, dass es direkt in WhatsApp, Instagram, Facebook, Messenger und Threads verfügbar ist, ohne zusätzliche Installation, und weiterhin eine kostenlose Stufe für den alltäglichen Gebrauch bietet — allerdings hat Meta 2026 mit Meta One auch kostenpflichtige Abonnements eingeführt.", "q": "Meta AI vs ChatGPT: Welches ist besser für Studenten?"}]$x$::jsonb
 WHERE slug = 'meta-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Что такое Meta AI?", "a": "Meta AI — ассистент от Meta, встроенный в WhatsApp, Instagram, Facebook, Messenger, Threads и AI-очки Meta. С апреля 2026 года работает на Muse Spark — первой собственной модели Meta Superintelligence Labs, заменившей более ранний движок на базе Llama. Помогает отвечать на вопросы и решать задачи прямо в соцсетях, а с июля 2026 года умеет генерировать изображения благодаря модели Muse Image. Есть бесплатный тариф, а также платные подписки под брендом Meta One."}, {"q": "Meta AI лучше ChatGPT?", "a": "Прямого сравнения в описании нет: Meta AI с апреля 2026 года работает на собственной модели Muse Spark от Meta Superintelligence Labs, а не на Llama, как раньше. Главное преимущество Meta AI — встроенность прямо в WhatsApp, Instagram, Facebook, Messenger и Threads, благодаря чему не нужно переключаться между приложениями. Если нужен самостоятельный инструмент вне экосистемы Meta или открытые веса модели, стоит смотреть в сторону других решений."}]$x$::jsonb
 WHERE slug = 'meta-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Meta AI vs ChatGPT — що обрати?", "a": "Meta AI кращий для соціальних мереж і WhatsApp: він вбудований прямо в Instagram, Facebook, Messenger і Threads, тож не треба переходити в окремий застосунок. ChatGPT кращий, якщо потрібен окремий інструмент для складних завдань поза екосистемою Meta. Meta AI простіший у доступі там, де ви вже спілкуєтесь; ChatGPT — самостійний продукт."}, {"q": "Чи Meta AI безкоштовний?", "a": "Безкоштовний рівень залишається для базового використання, але з травня–червня 2026 року Meta запровадила платні підписки під брендом Meta One: для користувачів Meta One Plus за 7.99 дол/міс і Meta One Premium за 19.99 дол/міс, для бізнесу — Meta One Essential за 14.99 дол/міс і Meta One Advanced за 49.99 дол/міс. Тестування платних тарифів почалося в Сінгапурі, Гватемалі та Болівії і поступово поширюється на інші країни."}, {"q": "Що таке Muse Spark і як він пов'язаний з Meta AI?", "a": "Muse Spark — перша власна велика мовна модель від Meta Superintelligence Labs. З 8 квітня 2026 року саме вона живить Meta AI, замінивши попередній рушій на базі Llama. Це був помітний і суперечливий крок Meta від відкритих моделей лінійки Llama до закритої власної технології."}, {"q": "Meta AI в WhatsApp — що він вміє?", "a": "Meta AI в WhatsApp відповідає на запитання, допомагає писати й переписувати тексти, підсумовує переписки, допомагає в групових чатах, а з липня 2026 року ще й генерує зображення за допомогою власної моделі Muse Image. Оскільки асистент вбудований у застосунок, він може працювати з тим контекстом, який ви вже переглядаєте, без переходу в окреме вікно."}]$x$::jsonb
 WHERE slug = 'meta-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Meta AI מול ChatGPT — מה לבחור?", "a": "Meta AI מתאים למי שכבר נמצא ב-WhatsApp, Instagram, Facebook או Messenger ורוצה עוזר זמין בתוך האפליקציות עצמן, ללא צורך לפתוח כלי נפרד. ChatGPT מתאים יותר למי שמחפש כלי עצמאי לעבודה מורכבת. Meta AI פועל כיום על Muse Spark, המודל הקנייני הראשון של Meta Superintelligence Labs, ולא על מודל פתוח כמו בעבר."}, {"q": "האם Meta AI בחינם?", "a": "יש ל-Meta AI עדיין רמה חינמית לשימוש בסיסי, אך זה כבר לא כלי חינמי לחלוטין. בשנת 2026 השיקה Meta מנויים בתשלום תחת המותג Meta One: למשתמשים פרטיים Meta One Plus ב-7.99 דולר לחודש ו-Meta One Premium ב-19.99 דולר לחודש, ולעסקים Meta One Essential ב-14.99 דולר לחודש ו-Meta One Advanced ב-49.99 דולר לחודש. ההשקה בתשלום החלה בסינגפור, גואטמלה ובוליביה ומתרחבת בהדרגה למדינות נוספות."}, {"q": "איזה מודל מפעיל את Meta AI כיום?", "a": "נכון לאפריל 2026 Meta AI כבר לא פועל על Llama. הוא מופעל על ידי Muse Spark, המודל השפתי הקנייני הראשון של Meta Superintelligence Labs, במעבר משמעותי ושנוי במחלוקת מהגישה הפתוחה שאפיינה את סדרת Llama. בנוסף, ביולי 2026 הוסיפה Meta את Muse Image, מודל יצירת התמונות הפנימי הראשון שלה, ל-Meta AI."}, {"q": "Meta AI ב-WhatsApp — מה הוא יכול?", "a": "Meta AI ב-WhatsApp עונה על שאלות, מנסח ומשכתב טקסטים, מסכם שיחות ועוזר גם בקבוצות. כעת הוא גם מייצר תמונות באמצעות Muse Image. בזכות השילוב בתוך האפליקציה הוא יכול להגיב ישירות להקשר של מה שכבר פתוח מולכם, בלי לעבור לחלון נפרד."}]$x$::jsonb
 WHERE slug = 'meta-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Meta AI vs ChatGPT — lequel choisir ?", "a": "Meta AI a l'avantage d'être intégré directement dans WhatsApp, Instagram, Facebook, Messenger et Threads, avec un accès gratuit et des offres payantes Meta One pour plus de fonctionnalités. ChatGPT reste un outil autonome distinct. Le choix dépend surtout de l'endroit où vous voulez travailler : dans vos applications Meta au quotidien, ou dans un espace de travail indépendant."}, {"q": "Meta AI est-il gratuit ?", "a": "Meta AI propose toujours un accès gratuit pour un usage courant dans WhatsApp, Instagram, Facebook, Messenger et Threads. Depuis mai/juin 2026, Meta a toutefois lancé des abonnements payants sous la marque Meta One : Meta One Plus (7,99 $/mois) et Meta One Premium (19,99 $/mois) pour les particuliers, Meta One Essential (14,99 $/mois) et Meta One Advanced (49,99 $/mois) pour les entreprises. Ces offres payantes sont testées depuis juin 2026 à Singapour, au Guatemala et en Bolivie, avant un déploiement mondial."}, {"q": "Meta AI utilise-t-il encore Llama ?", "a": "Non. Llama était le modèle ouvert de Meta sur lequel Meta AI s'appuyait auparavant. Depuis l'annonce du 8 avril 2026, Meta AI fonctionne sur Muse Spark, le premier modèle propriétaire de Meta Superintelligence Labs, ce qui marque un abandon notable et controversé de l'approche à poids ouverts de la lignée Llama."}, {"q": "Meta AI dans WhatsApp — que peut-il faire ?", "a": "Meta AI dans WhatsApp répond aux questions, aide à rédiger et résumer des messages, et peut désormais générer des images grâce à Muse Image, ajouté en juillet 2026. Il est disponible dans les conversations classiques comme dans les groupes, directement là où vous discutez déjà."}]$x$::jsonb
 WHERE slug = 'meta-ai' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Meta AI vs ChatGPT — qual escolher?", "a": "Meta AI é indicado para quem já vive dentro do WhatsApp, Instagram, Facebook, Messenger ou Threads e quer um assistente integrado ali mesmo, com um nível gratuito disponível. Desde 2026 a Meta também oferece planos pagos Meta One para quem precisa de recursos adicionais. Para tarefas mais complexas fora do ecossistema Meta, um assistente independente como o ChatGPT pode ser mais indicado."}, {"q": "Meta AI é gratuito?", "a": "Meta AI mantém um nível gratuito para uso casual no WhatsApp, Instagram, Facebook, Messenger, Threads e nos óculos de IA da Meta. A partir de maio/junho de 2026, porém, a Meta passou a oferecer assinaturas pagas sob a marca Meta One: para consumidores, Meta One Plus por $7,99/mês e Meta One Premium por $19,99/mês; para empresas, Meta One Essential por $14,99/mês e Meta One Advanced por $49,99/mês. Os testes pagos começaram em Singapura, Guatemala e Bolívia e estão se expandindo globalmente."}, {"q": "O que é o Muse Spark e qual sua relação com o Meta AI?", "a": "Muse Spark é o primeiro modelo de linguagem proprietário criado pela Meta Superintelligence Labs, anunciado em 8 de abril de 2026. Ele substituiu o mecanismo anterior baseado em Llama, o que representou uma mudança significativa e controversa em relação à linha de modelos de peso aberto da Meta. Em julho de 2026, a Meta também lançou o Muse Image, seu primeiro modelo próprio de geração de imagens, incorporado ao Meta AI."}, {"q": "Meta AI no WhatsApp — o que ele faz?", "a": "No WhatsApp, o Meta AI responde perguntas, ajuda a redigir e reescrever textos, resume conversas e auxilia em chats de grupo, além de agora gerar imagens por meio do Muse Image. Por estar integrado ao próprio aplicativo, ele pode agir com base no contexto que você já está visualizando, sem precisar abrir uma janela separada."}]$x$::jsonb
 WHERE slug = 'meta-ai' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "What is Microsoft Copilot?", "a": "Microsoft Copilot is Microsoft's AI assistant integrated across Windows, Microsoft 365 (Word, Excel, Outlook, Teams), Edge, and Bing. It runs on OpenAI's GPT models, with the option to select Anthropic's Claude models in Copilot Chat, to assist with tasks across the Microsoft ecosystem."}, {"q": "How much does Microsoft Copilot cost?", "a": "Copilot Free costs nothing and covers chat, cited web search, Think Deeper, voice, and daily image boosts. Microsoft 365 Personal and Family raise usage limits, and Microsoft 365 Premium adds the highest consumer limits plus Copilot inside the Office apps. For organizations, the Microsoft 365 Copilot add-on runs around $18-25/user/month depending on the plan, with the enterprise add-on around $30/user/month."}, {"q": "What can Microsoft Copilot do in Excel?", "a": "Copilot in Excel can generate formulas, create pivot tables, summarize data, create charts, and answer questions about your spreadsheet in natural language."}, {"q": "Is Microsoft Copilot the same as GitHub Copilot?", "a": "No. Microsoft Copilot is a general-purpose AI assistant for Windows and M365 apps. GitHub Copilot is a separate product focused on code completion and development, available at github.com/features/copilot."}]$x$::jsonb
 WHERE slug = 'microsoft-copilot' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "Ist Microsoft Copilot dasselbe wie ChatGPT?", "a": "Nicht genau. Microsoft Copilot verwendet Modelle von OpenAI (aktuell aus der GPT-5-Familie) und lässt sich in Copilot Chat auch mit Claude von Anthropic nutzen, ist aber in Microsoft-Produkte mit Bing-Suchzugang integriert. ChatGPT ist OpenAIs Direktprodukt. Der kostenlose Copilot-Plan beinhaltet Bildgenerierung mit einem täglichen Limit."}, {"q": "Ist Microsoft Copilot kostenlos?", "a": "Ja. Microsoft Copilot hat einen kostenlosen Plan mit Webzugang, Bildgenerierung (rund 15 Boosts pro Tag) und Chat mit aktuellen GPT-Modellen, wenn Kapazität verfügbar ist. Microsoft 365 Copilot für Unternehmen erfordert eine zusätzliche Lizenz, der Enterprise-Zusatz liegt bei rund $30/Benutzer/Monat."}, {"q": "Kann Microsoft Copilot kostenlos Bilder generieren?", "a": "Ja. Copilot Web beinhaltet kostenlose Bildgenerierung mit rund 15 Generierungs-Boosts pro Tag auf der kostenlosen Stufe. Das ist einer seiner Vorteile gegenüber anderen kostenlosen Chat-Angeboten."}, {"q": "Was ist Microsoft Copilot?", "a": "Microsoft Copilot ist Microsofts KI-Assistent, der in Windows, Microsoft 365 (Word, Excel, Outlook, Teams), Edge und Bing integriert ist. Er basiert mittlerweile auf der GPT-5-Modellfamilie, um bei Aufgaben im gesamten Microsoft-Ökosystem zu helfen."}, {"q": "Was kostet Microsoft Copilot?", "a": "Kostenlos in Windows und Bing. Der Microsoft 365 Copilot-Zusatz für Unternehmen kostet je nach Plan etwa $18.00/Nutzer/Monat im Jahresrabatt bzw. $25.20 monatlich, der Enterprise-Zusatz liegt bei rund $30/Nutzer/Monat zusätzlich zu einem Microsoft 365-Abonnement, und Copilot Studio für eigene Agenten kostet $200/Monat."}, {"q": "Was kann Microsoft Copilot in Excel?", "a": "Copilot in Excel kann Formeln erstellen, Pivot-Tabellen anlegen, Daten zusammenfassen, Diagramme erstellen und Fragen zur Tabellenkalkulation in natürlicher Sprache beantworten."}, {"q": "Ist Microsoft Copilot dasselbe wie GitHub Copilot?", "a": "Nein. Microsoft Copilot ist ein Allzweck-KI-Assistent für Windows und M365-Apps. GitHub Copilot ist ein separates Produkt für Code-Vervollständigung auf github.com/features/copilot."}]$x$::jsonb
 WHERE slug = 'microsoft-copilot' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "В чём разница между Microsoft Copilot и ChatGPT?", "a": "Microsoft Copilot встроен в экосистему Microsoft 365 (Word, Excel, Teams) и работает на основе GPT. ChatGPT — автономный продукт OpenAI с более широким набором функций: GPTs, Deep Research, Sora, Canvas. Copilot — выбор для корпоративных пользователей Microsoft, ChatGPT — для универсальных задач."}, {"q": "Microsoft Copilot бесплатный?", "a": "Microsoft Copilot доступен бесплатно через браузер Edge и сайт copilot.microsoft.com. Отдельная подписка Copilot Pro была отменена в конце 2025 года — теперь расширенные лимиты и интеграция с приложениями Microsoft 365 доступны в составе Microsoft 365 Premium (около $19.99/мес)."}, {"q": "Лучше ли ChatGPT, чем Microsoft Copilot?", "a": "ChatGPT предлагает больше функций и более свежие возможности (Deep Research, Sora, Memory). Copilot выигрывает у пользователей Microsoft 365 благодаря глубокой интеграции в привычные приложения. Для корпоративного использования с Microsoft — Copilot, для универсальных задач — ChatGPT."}, {"q": "Что умеет Microsoft Copilot в Excel?", "a": "Copilot в Excel создаёт формулы, сводные таблицы, диаграммы, анализирует данные и отвечает на вопросы о таблицах на естественном языке."}, {"q": "Microsoft Copilot — это то же самое что GitHub Copilot?", "a": "Нет. Microsoft Copilot — универсальный AI-ассистент для Windows и приложений M365. GitHub Copilot — отдельный продукт для дополнения кода и разработки на github.com/features/copilot."}]$x$::jsonb
 WHERE slug = 'microsoft-copilot' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"a": "Microsoft Copilot побудований на моделях OpenAI (родина GPT-5) і вбудований у Microsoft 365. ChatGPT — прямий продукт OpenAI з більш широкою незалежною екосистемою. Для Microsoft 365 — Copilot; для загального ШІ — ChatGPT.", "q": "Microsoft Copilot та ChatGPT — в чому різниця?"}, {"a": "Базовий Copilot у Windows і Edge безкоштовний. Microsoft 365 Copilot для підприємств коштує близько $30/користувач/міс. Copilot+ PC — апаратна функція для нових пристроїв.", "q": "Чи Microsoft Copilot безкоштовний?"}, {"a": "Copilot в Excel може аналізувати дані, будувати формули, створювати зведені таблиці і пропонувати графіки. Він розуміє природну мову: «покажи мені продажі за Q1 у розрізі регіонів» — і Excel генерує потрібну аналітику.", "q": "Microsoft Copilot для Excel — що він вміє?"}, {"a": "Ні. Microsoft Copilot — універсальний AI-асистент для Windows і додатків M365. GitHub Copilot — окремий продукт для доповнення коду на github.com/features/copilot.", "q": "Microsoft Copilot і GitHub Copilot — це одне й те саме?"}]$x$::jsonb
 WHERE slug = 'microsoft-copilot' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Microsoft Copilot ו-ChatGPT — מה ההבדל?", "a": "Microsoft Copilot בנוי על מודלים ממשפחת GPT של OpenAI, וכיום ניתן לבחור בתוכו גם במודלי Claude של Anthropic, והוא משולב ב-Microsoft 365. ChatGPT הוא מוצר ישיר של OpenAI עם מערכת-אקולוגית עצמאית רחבה יותר. ל-Microsoft 365 — Copilot; ל-AI כללי — ChatGPT."}, {"q": "האם Microsoft Copilot בחינם?", "a": "Copilot בסיסי ב-Windows וב-Edge חינמי. Microsoft 365 Copilot לארגונים עולה בסביבות 30$/משתמש/חודש. Copilot+ PC הוא תכונת חומרה למכשירים חדשים."}, {"q": "Microsoft Copilot ב-Excel — מה הוא יכול?", "a": "Copilot ב-Excel יכול לנתח נתונים, לבנות נוסחאות, ליצור טבלאות ציר ולהציע גרפים. הוא מבין שפה טבעית: 'הצג לי מכירות Q1 לפי אזור' — ו-Excel מייצר את הניתוח הנדרש."}, {"q": "האם Microsoft Copilot זהה ל-GitHub Copilot?", "a": "לא. Microsoft Copilot הוא עוזר AI כללי ל-Windows ואפליקציות M365. GitHub Copilot הוא מוצר נפרד המתמקד בהשלמת קוד ב-github.com/features/copilot."}]$x$::jsonb
 WHERE slug = 'microsoft-copilot' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Microsoft Copilot et ChatGPT — quelle est la différence ?", "a": "Microsoft Copilot s'appuie sur les modèles d'OpenAI (la famille GPT) et, selon les offres, sur les modèles Claude d'Anthropic, intégrés dans Microsoft 365. ChatGPT est le produit direct d'OpenAI avec un écosystème indépendant plus large. Pour Microsoft 365, Copilot ; pour l'IA générale, ChatGPT."}, {"q": "Microsoft Copilot est-il gratuit ?", "a": "Copilot Free est gratuit et couvre le chat, la recherche web avec citations, Think Deeper, la voix et des boosts d'images quotidiens. Microsoft 365 Personal et Family augmentent les limites d'utilisation, et Microsoft 365 Premium ajoute Copilot dans les applications Office. Pour les entreprises, l'add-on Microsoft 365 Copilot coûte environ 18 $/utilisateur/mois en tarif promotionnel annuel, ou 25,20 $ en facturation mensuelle."}, {"q": "Microsoft Copilot pour Excel — que peut-il faire ?", "a": "Le descriptif ne détaille pas de fonctionnalités propres à Excel : dans les offres payantes de Microsoft 365, Copilot s'intègre directement dans Word, Excel, PowerPoint et Outlook pour la rédaction de documents et l'assistance conversationnelle."}, {"q": "Qu'est-ce que Microsoft Copilot ?", "a": "Microsoft Copilot est l'assistant IA de Microsoft intégré dans Windows, Edge, Bing et les applications Microsoft 365 (Word, Excel, PowerPoint, Outlook). Il repose désormais sur la famille de modèles GPT-5 d'OpenAI, avec la possibilité de sélectionner les modèles Claude d'Anthropic dans Copilot Chat."}, {"q": "Combien coûte Microsoft Copilot ?", "a": "Copilot Free est gratuit. Microsoft 365 Personal coûte environ 9,99 $/mois et Family environ 12,99 $/mois, avec des limites d'utilisation plus élevées. Microsoft 365 Premium est à 19,99 $/mois. Pour les entreprises, l'add-on Microsoft 365 Copilot coûte environ 18 $/utilisateur/mois en promo annuelle ou 25,20 $ en mensuel, et l'add-on entreprise tourne autour de 30 $/utilisateur/mois. Copilot Studio, pour créer des agents personnalisés, coûte 200 $/mois."}, {"q": "Que peut faire Microsoft Copilot dans Excel ?", "a": "Le descriptif ne précise pas de fonctionnalités spécifiques à Excel : dans les offres payantes de Microsoft 365, Copilot travaille directement dans Word, Excel, PowerPoint et Outlook pour la rédaction de documents et l'assistance conversationnelle."}, {"q": "Microsoft Copilot est-il la même chose que GitHub Copilot ?", "a": "Non. Microsoft Copilot est un assistant IA polyvalent pour Windows et les applications M365. GitHub Copilot est un produit séparé axé sur la complétion de code sur github.com/features/copilot."}]$x$::jsonb
 WHERE slug = 'microsoft-copilot' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Microsoft Copilot e ChatGPT — qual é a diferença?", "a": "Microsoft Copilot é construído sobre modelos da OpenAI (família GPT) e integrado ao Microsoft 365. ChatGPT é o produto direto da OpenAI, com um ecossistema independente maior. Para Microsoft 365, Copilot; para IA geral, ChatGPT."}, {"q": "Microsoft Copilot é gratuito?", "a": "O Copilot básico no Windows e Edge é gratuito. Microsoft 365 Copilot para empresas custa cerca de $30/usuário/mês. Copilot+ PC é um recurso de hardware para novos dispositivos."}, {"q": "Microsoft Copilot no Excel — o que ele faz?", "a": "Copilot no Excel pode analisar dados, criar fórmulas, gerar tabelas dinâmicas e sugerir gráficos. Ele entende linguagem natural: 'mostre as vendas do T1 por região' — e o Excel gera a análise necessária."}, {"q": "O que é o Microsoft Copilot?", "a": "O Microsoft Copilot é o assistente de IA da Microsoft integrado ao Windows, Microsoft 365 (Word, Excel, Outlook, Teams), Edge e Bing. Usa modelos da família GPT-5 da OpenAI para auxiliar com tarefas em todo o ecossistema Microsoft."}, {"q": "Quanto custa o Microsoft Copilot?", "a": "Grátis no Windows e Bing. O Microsoft 365 Copilot para empresas custa cerca de $30/usuário/mês além da assinatura Microsoft 365. PCs Copilot+ incluem recursos de IA adicionais no dispositivo."}, {"q": "O que o Microsoft Copilot pode fazer no Excel?", "a": "O Copilot no Excel pode gerar fórmulas, criar tabelas dinâmicas, resumir dados, criar gráficos e responder perguntas sobre sua planilha em linguagem natural."}, {"q": "O Microsoft Copilot é o mesmo que o GitHub Copilot?", "a": "Não. O Microsoft Copilot é um assistente de IA de uso geral para Windows e apps M365. O GitHub Copilot é um produto separado focado em conclusão de código em github.com/features/copilot."}]$x$::jsonb
 WHERE slug = 'microsoft-copilot' AND lang = 'pt';

