UPDATE tools SET faq = $x$[{"q": "¿Es Microsoft Copilot lo mismo que ChatGPT?", "a": "No exactamente. Microsoft Copilot usa modelos de OpenAI (la familia GPT) pero está integrado en productos Microsoft con acceso a Bing Search. ChatGPT es el producto directo de OpenAI. Copilot gratuito incluye generación de imágenes; ChatGPT Plus ($20/mes) tiene más funciones avanzadas."}, {"q": "¿Microsoft Copilot es gratuito?", "a": "Sí. Microsoft Copilot tiene un plan gratuito con acceso web, generación de imágenes (unos 15 boosts por día) y acceso a los modelos GPT más recientes cuando hay capacidad disponible. Microsoft 365 Copilot para empresas requiere licencia adicional desde alrededor de $30/usuario/mes."}, {"q": "¿Microsoft Copilot puede generar imágenes gratis?", "a": "Sí. Copilot web incluye generación de imágenes gratuitamente, con un límite de unos 15 boosts de imagen por día en el plan gratuito. Esta es una de sus principales ventajas frente al plan gratuito de ChatGPT."}, {"q": "¿Qué es Microsoft Copilot?", "a": "Microsoft Copilot es el asistente de IA de Microsoft integrado en Windows, Microsoft 365 (Word, Excel, Outlook, Teams), Edge y Bing. Usa los modelos GPT más recientes de OpenAI, y también permite elegir modelos Claude de Anthropic, para asistir con tareas en todo el ecosistema Microsoft."}, {"q": "¿Cuánto cuesta Microsoft Copilot?", "a": "Gratis en Windows y Bing, con acceso a los modelos GPT más recientes cuando hay capacidad disponible. Microsoft 365 Copilot para empresas añade un costo adicional de alrededor de $30/usuario/mes a una suscripción Microsoft 365."}, {"q": "¿Qué puede hacer Microsoft Copilot en Excel?", "a": "Copilot en Excel puede generar fórmulas, crear tablas dinámicas, resumir datos, crear gráficos y responder preguntas sobre tu hoja de cálculo en lenguaje natural."}, {"q": "¿Microsoft Copilot es lo mismo que GitHub Copilot?", "a": "No. Microsoft Copilot es un asistente de IA de propósito general para Windows y apps M365. GitHub Copilot es un producto separado enfocado en la compleción de código en github.com/features/copilot."}]$x$::jsonb
 WHERE slug = 'microsoft-copilot' AND lang = 'es';
